#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <nb.h>

#define MAX_GEARS 12
#define MAX_EDGES 16
#define MESH_EFF  0.96 /* 96% mechanical efficiency per spur gear mesh */

struct GearNode {
  int id;
  int axle;
  int teeth;
  double x_studs; /* axle X in 8mm stud units */
  double y_studs; /* axle Y in 8mm stud units */
  double z_plane; /* axial plane offset for compound gears */
  int color;      /* 1=Red, 2=Yellow, 4=Blue, 5=LightGrey, 6=DarkGrey */
  int solved;
  double rpm;
  double torque_mNm;
  double phase_deg;
};

/* Edge type: 0 = coaxially locked on same axle, 1 = external tooth mesh */
struct GearEdge {
  int u;
  int v;
  int kind;
  int conflict;
};

static struct GearNode gears[MAX_GEARS];
static int num_gears = 0;
static struct GearEdge edges[MAX_EDGES];
static int num_edges = 0;

void add_gear(int axle, int teeth, double x, double y, double z, int col) {
  int id = num_gears++;
  gears[id] = (struct GearNode){ id, axle, teeth, x, y, z, col, 0, 0.0, 0.0, 0.0 };
}

void add_edge(int u, int v, int kind) {
  edges[num_edges++] = (struct GearEdge){ u, v, kind, 0 };
}

int main(void) {
  int preset = (int)nb_get_int("gear_preset", 0);
  double motor_rpm = nb_get_number("motor_rpm", 180.0);
  double motor_torque = nb_get_number("motor_torque", 45.0);

  if (preset == 0) {
    /* 9:1 Compound Crawler:
       Axle 0 (x=-3): 8T (driver)
       Axle 1 (x=-1): 24T (driven) + coaxial 8T (stage 2 driver)
       Axle 2 (x=+1): 24T (output crank axle) */
    add_gear(0,  8, -3.0, 0.0,  0.0, 1); /* G0: 8T Red */
    add_gear(1, 24, -1.0, 0.0,  0.0, 5); /* G1: 24T Grey */
    add_gear(1,  8, -1.0, 0.0,  0.8, 1); /* G2: 8T Red coaxial */
    add_gear(2, 24,  1.0, 0.0,  0.8, 2); /* G3: 24T Yellow output */
    add_edge(0, 1, 1);
    add_edge(1, 2, 0);
    add_edge(2, 3, 1);
  } else if (preset == 1) {
    /* 1:5 High-Speed Overdrive:
       Axle 0 (x=-3): 40T driver
       Axle 1 (x=0):  8T high-speed follower + coaxial 16T
       Axle 2 (x=+2): 16T output crank */
    add_gear(0, 40, -3.0, 0.0, 0.0, 5);
    add_gear(1,  8,  0.0, 0.0, 0.0, 1);
    add_gear(1, 16,  0.0, 0.0, 0.8, 4);
    add_gear(2, 16,  2.0, 0.0, 0.8, 2);
    add_edge(0, 1, 1);
    add_edge(1, 2, 0);
    add_edge(2, 3, 1);
  } else if (preset == 2) {
    /* 15:1 Heavy Winch Compound Train:
       Axle 0 (x=-3.5): 8T
       Axle 1 (x=-1.5): 24T + coaxial 8T
       Axle 2 (x=+1.5): 40T output */
    add_gear(0,  8, -3.5, 0.0, 0.0, 1);
    add_gear(1, 24, -1.5, 0.0, 0.0, 5);
    add_gear(1,  8, -1.5, 0.0, 0.8, 4);
    add_gear(2, 40,  1.5, 0.0, 0.8, 2);
    add_edge(0, 1, 1);
    add_edge(1, 2, 0);
    add_edge(2, 3, 1);
  } else {
    /* Preset 3: Jammed 3-Gear Odd Cycle Triangle + Output
       Three 16T gears mutually meshing in a triangle lock up! */
    add_gear(0, 16, -2.0,  0.0,   0.0, 1);
    add_gear(1, 16,  0.0,  0.0,   0.0, 5);
    add_gear(2, 16, -1.0,  1.732, 0.0, 4);
    add_gear(3, 24,  2.5,  0.0,   0.0, 2);
    add_edge(0, 1, 1);
    add_edge(1, 2, 1);
    add_edge(2, 0, 1); /* Closing the odd-length mesh cycle jams the train! */
    add_edge(1, 3, 1);
  }

  /* BFS kinematic solver from Gear 0 */
  gears[0].solved = 1;
  gears[0].rpm = motor_rpm;
  gears[0].torque_mNm = motor_torque;
  gears[0].phase_deg = 0.0;

  int queue[MAX_GEARS], head = 0, tail = 0;
  queue[tail++] = 0;
  int jammed = 0;

  while (head < tail) {
    int u = queue[head++];
    for (int e = 0; e < num_edges; e++) {
      int v = -1;
      if (edges[e].u == u) v = edges[e].v;
      else if (edges[e].v == u) v = edges[e].u;
      if (v < 0) continue;

      double expected_rpm, expected_torque, expected_phase;
      if (edges[e].kind == 0) {
        /* Coaxial: identical angular velocity, accumulated shaft torque */
        expected_rpm = gears[u].rpm;
        expected_torque = gears[u].torque_mNm;
        expected_phase = gears[u].phase_deg;
      } else {
        /* Spur mesh: opposite rotation, scaled by tooth ratio Z_u / Z_v */
        double ratio = (double)gears[u].teeth / (double)gears[v].teeth;
        expected_rpm = -gears[u].rpm * ratio;
        expected_torque = (gears[u].torque_mNm / ratio) * MESH_EFF;
        /* Starting angle so the teeth interleave. Each gear has a tooth centred at its
           own angle 0. Where the two pitch circles touch (direction alpha from u to v),
           v must have a gap opposite u's tooth pattern:
             (alpha - phase_u) Z_u + (alpha + pi - phase_v) Z_v = pi  (mod 2 pi),
           and turning at the ratio above keeps that true for ever. */
        double alpha = atan2(gears[v].y_studs - gears[u].y_studs, gears[v].x_studs - gears[u].x_studs);
        double phase_u = gears[u].phase_deg * 3.14159265358979 / 180.0;
        double phase_v = alpha + 3.14159265358979
                       + ((alpha - phase_u) * gears[u].teeth - 3.14159265358979) / (double)gears[v].teeth;
        expected_phase = phase_v * 180.0 / 3.14159265358979;
      }

      if (!gears[v].solved) {
        gears[v].solved = 1;
        gears[v].rpm = expected_rpm;
        gears[v].torque_mNm = expected_torque;
        gears[v].phase_deg = expected_phase;
        queue[tail++] = v;
      } else {
        /* Verify cycle consistency */
        if (fabs(gears[v].rpm - expected_rpm) > 1e-3) {
          edges[e].conflict = 1;
          jammed = 1;
        }
      }
    }
  }

  int out_id = num_gears - 1;
  double total_ratio = gears[out_id].rpm != 0.0 ? fabs(motor_rpm / gears[out_id].rpm) : 0.0;

  printf("=== Gear Train Kinematics & Torque Solver ===\n");
  printf("Input Motor: %.1f RPM @ %.1f mN*m (%.2f W mechanical power)\n",
         motor_rpm, motor_torque, (motor_rpm * 2.0 * 3.14159265 / 60.0) * (motor_torque / 1000.0));
  printf("Kinematic Status: %s\n\n",
         jammed ? "JAMMED! Odd-cycle gear loop locks rotation ( ω_v != -ω_u * Z_u/Z_v )"
                : "FREE RUNNING (All mesh constraints satisfied)");

  printf("%-6s %-6s %-7s %12s %14s %12s\n",
         "Gear", "Axle", "Teeth", "Pitch R(mm)", "Speed (RPM)", "Torque(mNm)");
  printf("-----------------------------------------------------------------\n");
  for (int i = 0; i < num_gears; i++) {
    printf("G%-5d A%-5d %4dT %12.1f %14.2f %12.2f\n",
           gears[i].id, gears[i].axle, gears[i].teeth,
           gears[i].teeth * 0.5,
           jammed ? 0.0 : gears[i].rpm,
           jammed ? 0.0 : gears[i].torque_mNm);
  }

  static char json[16384];
  int pos = 0;
  pos += snprintf(json + pos, sizeof(json) - pos,
    "{\"preset\":%d,\"jammed\":%d,\"motorRpm\":%.1f,\"motorTorque\":%.1f,"
    "\"outRpm\":%.2f,\"outTorque\":%.2f,\"ratio\":%.2f,\"gears\":[",
    preset, jammed, motor_rpm, motor_torque,
    jammed ? 0.0 : gears[out_id].rpm,
    jammed ? 0.0 : gears[out_id].torque_mNm,
    total_ratio);

  for (int i = 0; i < num_gears; i++) {
    pos += snprintf(json + pos, sizeof(json) - pos,
      "%s{\"id\":%d,\"axle\":%d,\"teeth\":%d,\"x\":%.3f,\"y\":%.3f,\"z\":%.3f,"
      "\"color\":%d,\"rpm\":%.3f,\"torque\":%.2f,\"phase\":%.2f}",
      i ? "," : "",
      gears[i].id, gears[i].axle, gears[i].teeth,
      gears[i].x_studs, gears[i].y_studs, gears[i].z_plane,
      gears[i].color, gears[i].rpm, gears[i].torque_mNm, gears[i].phase_deg);
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "],\"edges\":[");
  for (int e = 0; e < num_edges; e++) {
    pos += snprintf(json + pos, sizeof(json) - pos,
      "%s{\"u\":%d,\"v\":%d,\"kind\":%d,\"conflict\":%d}",
      e ? "," : "", edges[e].u, edges[e].v, edges[e].kind, edges[e].conflict);
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "]}");
  nb_set_json("gear_train", json);
  return 0;
}

// Two gears with Z1 and Z2 teeth sit (Z1 + Z2) / 2 mm apart; beam holes are 8 mm apart.
const SIZES = [8, 12, 16, 20, 24, 36, 40];
const gcd = (a, b) => (b ? gcd(b, a % b) : a);

const rows = [];
console.log('pairs that fit along a straight beam:');
for (const a of SIZES) {
  for (const b of SIZES) {
    const studs = (a + b) / 2 / 8;
    const fit = Number.isInteger(studs) ? 'whole studs' : Number.isInteger(studs * 2) ? 'half a stud' : 'neither';
    rows.push({ small: a + 'T', large: b + 'T', studs, fit });
    if (fit === 'whole studs' && a <= b) {
      const g = gcd(a, b);
      console.log(`  ${a}T + ${b}T: ${studs} hole${studs === 1 ? '' : 's'} apart, ${b / g} : ${a / g}`);
    }
  }
}

const order = SIZES.map((z) => z + 'T');
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: 'Distance between the axles, in 8 mm studs',
  width: 420,
  height: 420,
  data: { values: rows },
  encoding: {
    x: { field: 'small', type: 'ordinal', sort: order, title: 'one gear' },
    y: { field: 'large', type: 'ordinal', sort: order, title: 'the other gear' },
  },
  layer: [
    {
      mark: { type: 'rect', tooltip: true },
      encoding: {
        color: {
          field: 'fit', type: 'nominal', title: 'fits a straight beam?',
          scale: { domain: ['whole studs', 'half a stud', 'neither'], range: ['#10b981', '#f59e0b', '#475569'] },
        },
      },
    },
    { mark: { type: 'text', color: '#0f172a', fontWeight: 'bold' }, encoding: { text: { field: 'studs', type: 'quantitative', format: '.3~f' } } },
  ],
};
